method can_arrange(arr: seq<int>) returns (result: int)
    requires |arr| > 0 // The array must not be empty
    ensures (result == -1) ==> forall i :: 0 <= i < |arr| - 1 ==> arr[i] < arr[i + 1] // No element is found
    ensures (result >= 0 && result < |arr|) ==> arr[result] >= arr[result - 1] // Element found that is not greater than or equal to its predecessor
    ensures result == -1 || (result >= 0 && arr[result] < arr[result + 1]) // If a valid index is found, ensure it doesn't violate the condition in the postcondition
{
    var i := |arr| - 1;
    result := -1;
    while i > 0
        invariant 0 <= i <= |arr| // i is within the bounds of the array
        invariant result == -1 || (result >= 0 && result < i && arr[result] >= arr[result - 1]) // The last index found
    {
        if arr[i] < arr[i - 1] {
            result := i; // Found an index where the current element is not greater than or equal to the previous
            break; // Exit loop since we found our result
        }
        i := i - 1; // Move to the previous element
    }
}
